public class Main {
    static final int INF = 1_000_000_000;
    static int[] head, to, cap, cost, next;
    static int ne;
    static int NV;

    static void addEdge(int u, int v, int c, int w) {
        to[ne] = v; cap[ne] = c; cost[ne] = w; next[ne] = head[u]; head[u] = ne; ne++;
        to[ne] = u; cap[ne] = 0; cost[ne] = -w; next[ne] = head[v]; head[v] = ne; ne++;
    }

    static int minCostMaxFlow(int S, int T) {
        int flow = 0, costTotal = 0;
        int[] d = new int[NV];
        int[] p = new int[NV];
        boolean[] inqueue = new boolean[NV];
        Queue<Integer> q = new ArrayDeque<>();
        while (true) {
            Arrays.fill(d, INF);
            Arrays.fill(inqueue, false);
            d[S] = 0;
            q.add(S);
            inqueue[S] = true;
            while (!q.isEmpty()) {
                int v = q.poll();
                inqueue[v] = false;
                for (int x = head[v]; x != -1; x = next[x]) {
                    int u = to[x];
                    if (cap[x] > 0 && d[v] + cost[x] < d[u]) {
                        d[u] = d[v] + cost[x];
                        p[u] = x;
                        if (!inqueue[u]) {
                            q.add(u);
                            inqueue[u] = true;
                        }
                    }
                }
            }
            if (d[T] == INF) break;
            int df = INF;
            for (int i = T; i != S; i = to[p[i]^1]) {
                df = Math.min(df, cap[p[i]]);
            }
            for (int i = T; i != S; i = to[p[i]^1]) {
                cap[p[i]] -= df;
                cap[p[i]^1] += df;
            }
            flow += df;
            costTotal += df * d[T];
        }
        return costTotal;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] nm = br.readLine().split("\\s+");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);
        int[][] A = new int[n+1][m+1];
        for (int i = 1; i <= n; i++) {
            String[] line = br.readLine().split("\\s+");
            for (int j = 1; j <= m; j++) {
                A[i][j] = Integer.parseInt(line[j-1]);
            }
        }

        int N = n * m;
        int S = 0;
        int T = N + 1;
        NV = N + 2;
        // max edges: each cell up to 4 edges, plus source/sink edges. Total addEdge calls <= 5*N. Each adds 2 edges.
        int MAXE = 10 * N + 10;
        head = new int[NV];
        Arrays.fill(head, -1);
        to = new int[MAXE];
        cap = new int[MAXE];
        cost = new int[MAXE];
        next = new int[MAXE];
        ne = 0;

        // helper functions
        // group: (i+j)%2
        // id: (i-1)*m + j
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int id = (i-1)*m + j;
                if (((i+j)&1) == 0) {
                    addEdge(S, id, 1, 0);
                } else {
                    addEdge(id, T, 1, 0);
                }
            }
        }

        int[] di = {-1, 1, 0, 0};
        int[] dj = {0, 0, -1, 1};
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (((i+j)&1) == 0) {
                    int u = (i-1)*m + j;
                    for (int dir = 0; dir < 4; dir++) {
                        int ni = i + di[dir];
                        int nj = j + dj[dir];
                        if (ni >= 1 && ni <= n && nj >= 1 && nj <= m) {
                            int v = (ni-1)*m + nj;
                            int c = (A[i][j] != A[ni][nj]) ? 1 : 0;
                            addEdge(u, v, 1, c);
                        }
                    }
                }
            }
        }

        int ans = minCostMaxFlow(S, T);
        System.out.println(ans);
    }
}

