#include <bits/stdc++.h>
using namespace std;
int A[81][81];
struct Edge{
	int to, cap, cost, next;
};
Edge E[30000];
int head[7000], ne = 1;
int NV;
inline void addEdge(int from, int to, int cap, int cost) {
	E[++ne] = {to, cap, cost, head[from]}, head[from] = ne;
	E[++ne] = {from, 0, -cost, head[to]}, head[to] = ne;
}
int d[7000], p[7000];
bool inqueue[7000];
pair<int, int> mcmf(int S, int T) {
	int f = 0, c = 0;
	while(1) {
		for(int i = 0; i < NV; ++i) d[i] = 1e9;
		queue<int> Q;
		Q.push(S); d[S] = 0;
		while(!Q.empty()) {
			auto v = Q.front(); Q.pop();
			inqueue[v] = 0;
			for(int x = head[v]; x; x = E[x].next) {
				int &u = E[x].to, &cap = E[x].cap, &cost = E[x].cost;
				if(cap > 0 and d[v] + cost < d[u]) {
					d[u] = d[v] + cost;
					p[u] = x;
					if(!inqueue[u]) Q.push(u), inqueue[u] = 1;
				}
			}
		}
		if(d[T] == 1e9) break;
		int df = 1e9;
		for(int i = T; i != S; i = E[p[i]^1].to)
			df = min(df, E[p[i]].cap);
		for(int i = T; i != S; i = E[p[i]^1].to)
			E[p[i]].cap -= df, E[p[i]^1].cap += df;
		f += df, c += df * d[T];
	}
	return {f, c};
}
int n, m;
inline int group(int i, int j) {
	return (i + j) & 1;
}
inline int id(int i, int j) {
	return (i-1)*m+j;
}
int main() {
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> n >> m;
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			cin >> A[i][j];
	int S = 0, T = 6789;
	NV = 6790;
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j) {
			if(group(i, j) == 0)
				addEdge(S, id(i, j), 1, 0);
			else
				addEdge(id(i, j), T, 1, 0);
		}
	for(int i = 1; i <= n; ++i) {
		for(int j = 1; j <= m; ++j) {
			if(group(i, j) == 0) {
				if(i-1 >= 1)
					addEdge(id(i, j), id(i-1, j), 1, A[i][j] != A[i-1][j]);
				if(i+1 <= n)
					addEdge(id(i, j), id(i+1, j), 1, A[i][j] != A[i+1][j]);
				if(j-1 >= 1)
					addEdge(id(i, j), id(i, j-1), 1, A[i][j] != A[i][j-1]);
				if(j+1 <= m)
					addEdge(id(i, j), id(i, j+1), 1, A[i][j] != A[i][j+1]);
			}
		}
	}
	auto ans = mcmf(S, T);
	cout << ans.second << endl;
	return 0;
}
